 function examDate(r){return (r.date||'날짜 미기록')+' '+(r.time||'시각 미기록');}
 function listDate(r){if(r.time!==undefined)return examDate(r);const cached=listTimeCache.get(r.id);return cached&&Date.now()-cached.at<60000?cached.error?r.date+' · 시각 조회 실패':examDate({...r,time:cached.time}):r.date+' · 시각 확인 중';}
