 function syncFindings(ids){for(const id of ids){const el=root.querySelector('[data-finding="'+id+'"]');if(el)el.value=draft.findings[id]||'';root.querySelectorAll('[data-quick="'+id+'"]').forEach(q=>q.setAttribute('aria-pressed',String(q.dataset.value===(draft.findings[id]||''))));const cell=el?.closest('[data-cell]');if(cell){cell.classList.remove('nr-just-changed');void cell.offsetWidth;cell.classList.add('nr-just-changed');}}}
 function applyFindings(values){if(!edit()||conflict||!valid(key()))return;const changes=Object.entries(values).filter(([id,value])=>byId[id]&&!same(draft.findings[id],value)).map(([id,after])=>({id,before:draft.findings[id],after}));if(!changes.length)return;for(const c of changes){if(c.after===undefined)delete draft.findings[c.id];else draft.findings[c.id]=c.after;}undoStack.push({record:item.id,changes});if(undoStack.length>10)undoStack.shift();syncFindings(changes.map(c=>c.id));changed();}
 function undoFindings(){if(!edit()||conflict||!valid(key()))return;const last=undoStack.pop();if(!last)return;if(last.record!==item.id||last.changes.some(c=>!same(draft.findings[c.id],c.after))){undoStack=[];notify('현재 결과가 변경되어 실행 취소할 수 없습니다.');return;}for(const c of last.changes){if(c.before===undefined)delete draft.findings[c.id];else draft.findings[c.id]=c.before;}syncFindings(last.changes.map(c=>c.id));changed();notify('마지막 검사 입력을 되돌렸습니다.');}

 function jumpTo(id){const target=root.querySelector('#'+id);if(!target)return;if(target.hidden&&reviewMode!=='all'){target.hidden=false;const notice=document.createElement('div');notice.className='nr-review-empty';notice.dataset.reviewEmpty='';notice.innerHTML='<p>현재 보기 조건에 해당하는 '+esc(schema.groups[id.slice(3)]||'검사')+' 결과가 없습니다.</p>'+(edit()?'<button type="button" data-show-input>전체 · 입력으로 전환</button>':'');target.append(notice);notice.querySelector('button')?.addEventListener('click',()=>{reviewMode='all';editTarget='';applyReview();jumpTo(id);});}if(target.tagName==='DETAILS')target.open=true;navActive=id;const offset=(root.querySelector('.nr-head')?.getBoundingClientRect().height||0)+12;g.scrollTo({top:g.scrollY+target.getBoundingClientRect().top-offset,behavior:'instant'});updateNav();}
 function updateNav(){if(mode!=='record')return;const buttons=[...root.querySelectorAll('[data-jump]')],offset=(root.querySelector('.nr-head')?.getBoundingClientRect().bottom||0)+16;const entries=buttons.map(b=>{const el=root.querySelector('#'+b.dataset.jump);return {id:b.dataset.jump,top:el?.getBoundingClientRect().top,hidden:!el||el.hidden};}).filter(x=>!x.hidden&&x.top<=offset);if(entries.length){const max=Math.max(...entries.map(x=>x.top)),nearest=entries.filter(x=>Math.abs(x.top-max)<3);navActive=nearest.some(x=>x.id===navActive)?navActive:nearest[0].id;}else navActive=buttons[0]?.dataset.jump;let activeChanged=false;buttons.forEach(b=>{const active=b.dataset.jump===navActive;if(active&&b.getAttribute('aria-current')!=='true')activeChanged=true;b.setAttribute('aria-current',String(active));});if(activeChanged)revealNav();navEdges();}
 function onScroll(){if(navFrame!==null)return;navFrame=requestAnimationFrame(()=>{navFrame=null;updateNav();queueVisibleTimes();});}
 function renderRecheck(b){if(!recheckSource||!edit())return;const box=document.createElement('details');box.className='nr-card nr-recheck';box.dataset.detail='recheck-import';box.innerHTML='<summary>이전 병력·계획 가져오기 · '+esc(recheckSource.date)+'<small>검사 결과와 검사 조건은 새로 기록합니다.</small></summary>'+['history','plan'].map(k=>'<div><b>'+textLabels[k]+'</b><p>'+esc(recheckSource[k]||'이전 내용 없음')+'</p><button data-import="'+k+'" '+(!recheckSource[k]||imported.has(k)?'disabled':'')+'>'+(imported.has(k)?'가져옴':'이 내용 가져오기')+'</button></div>').join('');b.querySelector('#nr-basic')?.after(box);box.querySelectorAll('[data-import]').forEach(btn=>btn.onclick=()=>{if(!edit()||conflict||!valid(key()))return;const k=btn.dataset.import;if(imported.has(k)||!recheckSource[k])return;const combined=[draft[k],recheckSource[k]].filter(Boolean).join('\n');if(combined.length>4000){notify('기존 입력과 이전 내용을 합치면 4,000자를 초과합니다. 내용을 줄인 뒤 가져와주세요.');return;}draft[k]=combined;imported.add(k);const field=root.querySelector('[data-field="'+k+'"]');if(field)field.value=draft[k];btn.disabled=true;btn.textContent='가져옴';changed('text');});}
 async function copySummary(){const token=key();if((dirty||pending)&&!await save())return;if(!valid(token)||!draft)return;const entries=summary(draft),ab=entries.filter(x=>!limitedFinding(draft.findings[x.id])),lim=entries.filter(x=>limitedFinding(draft.findings[x.id]));const normal=schema.rows.map(r=>{const sides=r.sides.filter(side=>{const id=r.key+(side?'.'+side:'');return !!draft.findings[id]&&draft.findings[id]===r.normal;});return sides.length?examName(r)+(sides.some(Boolean)?' ('+sides.map(side=>schema.sides[side]).join('·')+')':''):'';}).filter(Boolean);const text=[item.patient.name+' · '+patientText(),draft.date+' '+draft.time,'검사 조건: '+fieldValue('context',draft.context),'기록 '+Object.keys(draft.findings).length+' / '+allFields.length+'항목','정상으로 기록한 검사: '+(normal.join('; ')||'없음'),'미검사: '+allFields.filter(f=>!draft.findings[f.id]).length+'항목 · 정상으로 간주하지 않음',draft.history?'병력: '+draft.history:'',draft.medications?'복용약·검사 제한: '+draft.medications:'','이상 소견: '+(ab.map(x=>x.label+': '+x.value).join('; ')||'기록된 이상 소견 없음'),'평가 제한: '+(lim.map(x=>x.label+': '+x.value).join('; ')||'기록된 제한 없음'),draft.examNote?'검사 메모: '+draft.examNote:'','병변 위치(수의사): '+fieldValue('localization',draft.localization)+' · '+fieldValue('laterality',draft.laterality),draft.assessment?'판단: '+draft.assessment:'',draft.plan?'계획: '+draft.plan:'','검사자: '+(draft.veterinarian||'미입력')].filter(Boolean).join('\n');try{await navigator.clipboard.writeText(text);if(valid(token))notify('진료 요약을 복사했습니다.');}catch{if(!valid(token))return;let box=root.querySelector('[data-copy-fallback]');if(!box){box=document.createElement('section');box.className='nr-card';box.dataset.copyFallback='';box.innerHTML='<label>진료 요약 · 선택한 내용을 복사하세요<textarea readonly rows="8" aria-label="진료 요약 복사본"></textarea></label><button type="button">닫기</button>';box.querySelector('button').onclick=()=>box.remove();root.querySelector('[data-nr-body]').prepend(box);}const field=box.querySelector('textarea');field.value=text;field.focus();field.select();notify('자동 복사가 지원되지 않아 복사할 내용을 표시했습니다.');}}


 function clearInputErrors(el){const fields=el?[el]:[...root.querySelectorAll('[aria-invalid=true]')];for(const field of fields){field.removeAttribute('aria-invalid');const err=field.parentElement?.querySelector('[data-input-error]');if(err){field.removeAttribute('aria-describedby');err.remove();}}}
 function showInputError(el,message){if(el){for(let p=el.parentElement;p&&p!==root;p=p.parentElement)if(p.tagName==='DETAILS')p.open=true;el.setAttribute('aria-invalid','true');const error=document.createElement('span');error.dataset.inputError='';error.className='nr-input-error';error.id='nr-input-error';error.textContent=message;el.after(error);el.setAttribute('aria-describedby',error.id);el.scrollIntoView({block:'center',behavior:'instant'});el.focus({preventScroll:true});}notify(message);}
 function navEdges(){const nav=root.querySelector('.nr-jumps');if(!nav)return;const overflow=nav.scrollWidth>nav.clientWidth+2;root.querySelectorAll('[data-nav-shift]').forEach(b=>{b.hidden=!overflow;b.disabled=Number(b.dataset.navShift)<0?nav.scrollLeft<=1:nav.scrollLeft+nav.clientWidth>=nav.scrollWidth-2;});}
 function revealNav(){const nav=root.querySelector('.nr-jumps'),active=nav?.querySelector('[aria-current=true]');if(!active)return;const a=active.getBoundingClientRect(),n=nav.getBoundingClientRect();if(a.left<n.left)nav.scrollLeft+=a.left-n.left;else if(a.right>n.right)nav.scrollLeft+=a.right-n.right;}

 function refreshSummary(){const el=root.querySelector('[data-summary]');if(el&&draft){const entries=summary(draft),limited=entries.filter(x=>limitedFinding(draft.findings[x.id])),abnormal=entries.filter(x=>!limitedFinding(draft.findings[x.id]));const block=(label,list,cls)=>'<div class="'+cls+'"><b>'+label+' '+list.length+'항목</b>'+(list.length?'<ul>'+list.map(x=>'<li><b>'+esc(x.label)+'</b> '+esc(x.value)+(edit()?'<button data-summary-edit="'+x.id+'">수정</button>':'')+'</li>').join('')+'</ul>':'<p>해당 항목 없음</p>')+'</div>';el.innerHTML='<p class="nr-help">기록 '+Object.keys(draft.findings).length+'항목 · 미검사 '+(allFields.length-Object.keys(draft.findings).length)+'항목</p>'+block('이상 소견',abnormal,'nr-abnormal-summary')+block('평가 제한',limited,'nr-limited-summary');el.querySelectorAll('[data-summary-edit]').forEach(b=>b.onclick=()=>editFinding(b.dataset.summaryEdit));}if(comparing&&comparisonOpen)updateComparison();renderAid();applyReview();}
 function updateStaff(){const el=root.querySelector('#nr-members');if(el)el.innerHTML=members.map(m=>'<option value="'+esc(m.display_name)+'"></option>').join('');const status=root.querySelector('[data-member-status]');if(status){status.innerHTML=memberError?'<span>'+esc(memberError)+'</span> <button data-staff-retry>다시 불러오기</button>':'';status.querySelector('button')?.addEventListener('click',()=>void staff());}}
 function detailKey(d){return d.dataset.detail||d.id||((d.closest('section')?.id||'')+'|'+d.querySelector('summary')?.textContent);}
